import java.util.Scanner; import java.util.ArrayList; import java.util.List; public class TestClass { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); List<Integer> a = new ArrayList<Integer>(); for (int i = 0; i < n; i++) { a.add(sc.nextInt()); } List<Integer> b = new ArrayList<Integer>(); for (int i = 0; i < n; i++) { b.add(sc.nextInt()); } int time = 0; int head = 0; for (int i = 0; i < n; i++) { int target = b.get(i); int pos = -1; for (int j = 0; j < a.size(); j++) { if (a.get(j) == target) { pos = j; break; } } int rotations = (pos - head + a.size()) % a.size(); time += rotations + 1; a.remove(pos); if (a.size() > 0) { head = pos % a.size(); } } System.out.println(time); } }